package com.pranit.helpdesk.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="ticket_comments") public class Comment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private Ticket ticket; @ManyToOne(fetch=FetchType.LAZY,optional=false) private User author; @Column(nullable=false,length=4000) private String message; @Column(nullable=false) private LocalDateTime createdAt; @PrePersist void prePersist(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public Ticket getTicket(){return ticket;} public void setTicket(Ticket v){ticket=v;} public User getAuthor(){return author;} public void setAuthor(User v){author=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
